double clipped_v = 0.0;
double heating = 0.0, cooling = 0.0, next_temp;
adcs_actuator_limit_t lim;
mt_mode_t cur_mode;

/* 初始输出 */
mt_output.applied_voltage_v = 0.0;
mt_output.winding_temperature_k = mt_state.winding_temperature_k;
mt_output.heating_w = 0.0;
mt_output.cooling_w = 0.0;

/* 有效性检查 */
if ((mt_input.enable == 0) ||
    (mt_input.telemetry == 0) ||
    (!isfinite(mt_input.telemetry->requested_voltage_v)) ||
    (!isfinite(mt_input.telemetry->ambient_temperature_k)) ||
    (!isfinite(mt_input.telemetry->dt_s)) ||
    (!isfinite(mt_state.winding_temperature_k)) ||
    (!isfinite(mt_config.max_voltage_v)) ||
    (!isfinite(mt_config.resistance_ohm)) ||
    (!isfinite(mt_config.capacity_j_k)) ||
    (!isfinite(mt_config.thermal_resistance_k_w)) ||
    (!isfinite(mt_config.trip_temperature_k)) ||
    (!isfinite(mt_config.reset_temperature_k)) ||
    (mt_config.max_voltage_v <= 0.0) ||
    (mt_config.resistance_ohm <= 0.0) ||
    (mt_config.capacity_j_k <= 0.0) ||
    (mt_config.thermal_resistance_k_w <= 0.0) ||
    (mt_config.reset_temperature_k >= mt_config.trip_temperature_k) ||
    (mt_config.max_trip_cycles > 1000U)) {
    mt_state.mode = MT_FAULT;
    mt_output.mode = MT_FAULT;
    mt_output.applied_voltage_v = 0.0;
    mt_output.winding_temperature_k = mt_state.winding_temperature_k;
    mt_output.heating_w = 0.0;
    mt_output.cooling_w = 0.0;
    return;
}

/* 限幅请求电压 */
lim.min_value = -mt_config.max_voltage_v;
lim.max_value =  mt_config.max_voltage_v;
lim.max_slew_per_s = 0.0;
if (adcs_limit_scalar(mt_input.telemetry->requested_voltage_v, &lim, &clipped_v) != ADCS_OK) {
    mt_state.mode = MT_FAULT;
    mt_output.mode = MT_FAULT;
    mt_output.applied_voltage_v = 0.0;
    mt_output.winding_temperature_k = mt_state.winding_temperature_k;
    mt_output.heating_w = 0.0;
    mt_output.cooling_w = 0.0;
    return;
}

/* 物理量预测 */
heating = (clipped_v * clipped_v) / mt_config.resistance_ohm;
cooling = (mt_state.winding_temperature_k - mt_input.telemetry->ambient_temperature_k)
          / mt_config.thermal_resistance_k_w;
next_temp = mt_state.winding_temperature_k
            + (heating - cooling) * mt_input.telemetry->dt_s / mt_config.capacity_j_k;

mt_output.heating_w = heating;
mt_output.cooling_w = cooling;

/* FAULT 保持 */
if (mt_state.mode == MT_FAULT) {
    mt_output.mode = MT_FAULT;
    mt_output.applied_voltage_v = 0.0;
    mt_output.winding_temperature_k = mt_state.winding_temperature_k;
    return;
}

/* OFF + enabled + valid 按 DRIVE 处理 */
if (mt_state.mode == MT_OFF) {
    cur_mode = MT_DRIVE;
} else {
    cur_mode = mt_state.mode;
}

if (cur_mode == MT_DRIVE) {
    if (next_temp >= mt_config.trip_temperature_k) {
        if ((mt_config.max_trip_cycles == 0U) ||
            (mt_state.trip_count < mt_config.max_trip_cycles)) {
            mt_state.trip_count = mt_state.trip_count + 1U;
            mt_state.mode = MT_COOL;
            mt_state.winding_temperature_k = next_temp;
            mt_output.mode = MT_COOL;
            mt_output.applied_voltage_v = 0.0;
            mt_output.winding_temperature_k = next_temp;
            return;
        } else {
            mt_state.mode = MT_FAULT;
            mt_output.mode = MT_FAULT;
            mt_output.applied_voltage_v = 0.0;
            mt_output.winding_temperature_k = next_temp;
            return;
        }
    } else {
        mt_state.mode = MT_DRIVE;
        mt_state.winding_temperature_k = next_temp;
        mt_output.mode = MT_DRIVE;
        mt_output.applied_voltage_v = clipped_v;
        mt_output.winding_temperature_k = next_temp;
        return;
    }
}

if (cur_mode == MT_COOL) {
    if (next_temp > mt_config.reset_temperature_k) {
        mt_state.mode = MT_COOL;
        mt_state.winding_temperature_k = next_temp;
        mt_output.mode = MT_COOL;
        mt_output.applied_voltage_v = 0.0;
        mt_output.winding_temperature_k = next_temp;
        return;
    } else {
        mt_state.mode = MT_DRIVE;
        mt_state.winding_temperature_k = next_temp;
        mt_output.mode = MT_DRIVE;
        mt_output.applied_voltage_v = clipped_v;
        mt_output.winding_temperature_k = next_temp;
        return;
    }
}

