    if (!isfinite(temp))
        valid = 0;
}
if (valid) {
    if ((!isfinite(mt_config.max_voltage_v)) || (mt_config.max_voltage_v <= 0.0))
        valid = 0;
    if ((!isfinite(mt_config.resistance_ohm)) || (mt_config.resistance_ohm <= 0.0))
        valid = 0;
    if ((!isfinite(mt_config.capacity_j_k)) || (mt_config.capacity_j_k <= 0.0))
        valid = 0;
    if ((!isfinite(mt_config.thermal_resistance_k_w)) || (mt_config.thermal_resistance_k_w <= 0.0))
