        valid = 0;
    if (!(mt_config.reset_temperature_k < mt_config.trip_temperature_k))
        valid = 0;
    if (mt_config.max_trip_cycles > 1000U)
        valid = 0;
}
if (valid) {
    if (mt_input.telemetry->dt_s <= 0.0)
        valid = 0;
}

if (!valid) {
    mt_state.mode = MT_FAULT;
    mt_output.mode = MT_FAULT;
    mt_output.applied_voltage_v = 0.0;
    mt_output.winding_temperature_k = temp;
    mt_output.heating_w = 0.0;
    mt_output.cooling_w = 0.0;
