    mt_state.trip_count = 0U;
    mt_state.mode = MT_OFF;
    mt_output.mode = MT_OFF;
    mt_output.applied_voltage_v = 0.0;
    mt_output.winding_temperature_k = temp;
    mt_output.heating_w = 0.0;
    mt_output.cooling_w = 0.0;
} else {
    adcs_actuator_limit_t limit;
    limit.min_value = -mt_config.max_voltage_v;
    limit.max_value = mt_config.max_voltage_v;
    limit.max_slew_per_s = 0.0;

