                    vapp = 0.0;
                    mode = MT_FAULT;
                }
            } else {
                mode = MT_DRIVE;
            }
        } else if (mode == MT_FAULT) {
            vapp = 0.0;
        } else if (mode == MT_COOL) {
            if (next_temp > mt_config.reset_temperature_k) {
                vapp = 0.0;
                mode = MT_COOL;
            } else {
                vapp = 0.0;
                mode = MT_DRIVE;
            }
        }

        mt_state.mode = mode;
        mt_state.winding_temperature_k = next_temp;
        mt_output.mode = mode;
